// Validate and restructure pipeline data for LLM
const input = $input.first().json;

let pipelineData;
if (input.pipeline_data) {
  pipelineData = typeof input.pipeline_data === 'string'
    ? JSON.parse(input.pipeline_data)
    : input.pipeline_data;
} else {
  throw new Error('No pipeline_data returned from PostgreSQL query');
}

// Calculate summary metrics
const pipeline = pipelineData.pipeline_by_stage || [];
const totalPipelineACV = pipeline.reduce((sum, s) => sum + Number(s.total_acv || 0), 0);
const totalDealCount = pipeline.reduce((sum, s) => sum + Number(s.deal_count || 0), 0);

const wins = (pipelineData.win_loss || []).filter(d => d.outcome === 'Closed_Won');
const losses = (pipelineData.win_loss || []).filter(d => d.outcome === 'Closed_Lost');
const wonACV = wins.reduce((sum, d) => sum + Number(d.acv || 0), 0);
const lostACV = losses.reduce((sum, d) => sum + Number(d.acv || 0), 0);

const forecast = pipelineData.forecast || [];
const commitForecast = forecast.find(f => f.category === 'Commit');
const bestCaseForecast = forecast.find(f => f.category === 'Best Case');
const closedWonQTD = forecast.reduce((sum, f) => sum + Number(f.closed_won_acv || 0), 0);
const commitTotal = commitForecast ? Number(commitForecast.total_acv || 0) : 0;

const enriched = {
  ...pipelineData,
  summary: {
    total_pipeline_acv: totalPipelineACV,
    total_open_deals: totalDealCount,
    new_opps_count: (pipelineData.new_opportunities || []).length,
    new_opps_acv: (pipelineData.new_opportunities || []).reduce((sum, o) => sum + Number(o.acv || 0), 0),
    stage_movements_count: (pipelineData.stage_movements || []).length,
    stalled_deals_count: (pipelineData.stalled_deals || []).length,
    stalled_deals_acv: (pipelineData.stalled_deals || []).reduce((sum, d) => sum + Number(d.acv || 0), 0),
    wins_count: wins.length,
    wins_acv: wonACV,
    losses_count: losses.length,
    losses_acv: lostACV,
    win_rate_count: (wins.length + losses.length) > 0
      ? Math.round(wins.length / (wins.length + losses.length) * 100)
      : null,
    win_rate_acv: (wonACV + lostACV) > 0
      ? Math.round(wonACV / (wonACV + lostACV) * 100)
      : null,
    forecast_commit_acv: commitTotal,
    forecast_best_case_acv: bestCaseForecast ? Number(bestCaseForecast.total_acv || 0) : 0,
    forecast_closed_won_qtd: closedWonQTD,
    forecast_accuracy_pct: commitTotal > 0
      ? Math.round(closedWonQTD / commitTotal * 100)
      : null
  },
  generated_at: new Date().toISOString()
};

return [{ json: enriched }];

