// Parse LLM response and format as Slack-compatible markdown
const pipelineData = $('Prepare & Enrich Data').first().json;
const llmResponse = $input.first().json;

// Parse the JSON from LLM response
let report;
try {
  if (typeof llmResponse.message === 'string') {
    let cleaned = llmResponse.message.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    report = JSON.parse(cleaned);
  } else if (llmResponse.message?.content) {
    let cleaned = llmResponse.message.content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    report = JSON.parse(cleaned);
  } else {
    report = llmResponse;
  }
} catch (e) {
  throw new Error(`Failed to parse LLM response: ${e.message}`);
}

// Pipeline Health emoji
const healthEmoji = {
  GREEN: ':large_green_circle:',
  YELLOW: ':large_yellow_circle:',
  RED: ':red_circle:'
};
const healthStatus = report.pipeline_health?.status || 'YELLOW';

// Severity emoji
const severityEmoji = { HIGH: ':rotating_light:', MEDIUM: ':warning:', LOW: ':information_source:' };

// Format currency
const fmtKRW = (v) => {
  if (v == null) return 'N/A';
  if (v >= 100000000) return `${(v / 100000000).toFixed(1)}억원`;
  if (v >= 10000) return `${(v / 10000).toFixed(0)}만원`;
  return `${v.toLocaleString()}원`;
};
const fmtUSD = (v) => {
  if (v == null) return 'N/A';
  if (v >= 1000000) return `$${(v / 1000000).toFixed(1)}M`;
  if (v >= 1000) return `$${(v / 1000).toFixed(0)}K`;
  return `$${v.toLocaleString()}`;
};

// Build Slack blocks
const period = pipelineData.report_period;
const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: `Weekly Ops Report | ${period.week_start} ~ ${period.week_end}` }
  },
  { type: 'divider' },

  // Executive Summary
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `${healthEmoji[healthStatus]} *Executive Summary*\n` +
        (report.executive_summary || []).map(b => `  • ${b}`).join('\n')
    }
  },
  { type: 'divider' },

  // Pipeline Health
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Pipeline Health: ${healthStatus}*\n` +
        `Total Pipeline: ${fmtUSD(report.pipeline_health?.total_pipeline_acv)} | ` +
        `Open Deals: ${report.pipeline_health?.total_open_deals || 0}\n` +
        (report.pipeline_health?.assessment || '')
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '*Stage Distribution:*\n' +
        (report.pipeline_health?.stage_distribution || []).map(s =>
          `  ${s.stage}: ${s.count}건 / ${fmtUSD(s.acv)} — ${s.comment}`
        ).join('\n')
    }
  },
  { type: 'divider' },

  // Risk Highlights
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '*Risk Highlights*\n' +
        (report.risk_highlights || []).map(r =>
          `${severityEmoji[r.severity] || ''} *[${r.severity}]* ${r.description}\n` +
          `  → ${r.recommended_action}` +
          (r.affected_deals?.length ? `\n  대상: ${r.affected_deals.join(', ')}` : '')
        ).join('\n\n')
    }
  },
  { type: 'divider' },

  // Win/Loss
  {
    type: 'section',
    fields: [
      {
        type: 'mrkdwn',
        text: `:trophy: *Wins*\n${report.win_loss_analysis?.wins?.count || 0}건 / ${fmtUSD(report.win_loss_analysis?.wins?.acv)}\n${report.win_loss_analysis?.wins?.patterns || 'N/A'}`
      },
      {
        type: 'mrkdwn',
        text: `:x: *Losses*\n${report.win_loss_analysis?.losses?.count || 0}건 / ${fmtUSD(report.win_loss_analysis?.losses?.acv)}\n${report.win_loss_analysis?.losses?.patterns || 'N/A'}`
      }
    ]
  },
  { type: 'divider' },

  // Forecast
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Forecast Update (Current Quarter)*\n` +
        `Commit: ${fmtUSD(report.forecast_update?.commit_acv)} | ` +
        `Best Case: ${fmtUSD(report.forecast_update?.best_case_acv)} | ` +
        `Closed Won QTD: ${fmtUSD(report.forecast_update?.closed_won_qtd)}\n` +
        `Accuracy: ${report.forecast_update?.accuracy_pct != null ? report.forecast_update.accuracy_pct + '%' : 'N/A'}\n` +
        (report.forecast_update?.commentary || '')
    }
  },
  { type: 'divider' },

  // Weekly Actions
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '*Weekly Actions*\n' +
        (report.weekly_actions || []).map((a, i) =>
          `*${i + 1}.* ${a.action}` +
          (a.owner_hint ? ` _(${a.owner_hint})_` : '') +
          (a.deadline_hint ? ` — ${a.deadline_hint}` : '') +
          (a.target_deals?.length ? `\n    대상: ${a.target_deals.join(', ')}` : '')
        ).join('\n')
    }
  },

  // Footer
  { type: 'divider' },
  {
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text: `Generated by Ops Analyst Agent | ${new Date().toISOString()} | gpt-4o`
      }
    ]
  }
];

const slackMessage = { blocks };

return [{
  json: {
    report,
    slack_message: slackMessage,
    db_record: {
      agent_name: 'ops_analyst',
      trigger_type: 'schedule',
      input_summary: `Weekly report ${period.week_start} ~ ${period.week_end}. Pipeline: ${fmtUSD(pipelineData.summary.total_pipeline_acv)}, Open deals: ${pipelineData.summary.total_open_deals}`,
      output_summary: `Health: ${healthStatus}, Risks: ${(report.risk_highlights || []).length}, Actions: ${(report.weekly_actions || []).length}`,
      report_json: report
    }
  }
}];
